import{u as n,o as r,c as o,j as e,k as s,F as l,a8 as d,e as h,p as c}from"./chunks/framework.fPNBP_58.js";const p=["markdown-url"],u={"data-allow-mismatch":"",style:{display:"none"}},b=JSON.parse('{"title":"Flood Evacuation","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"flood-evacuation","file":"https://gtif-austria.github.io/public-narratives/flood-evacuation.md","title":"Flood Evacuation"},"relativePath":"narratives/flood-evacuation.md","filePath":"narratives/[narrative].md"}'),m={name:"narratives/flood-evacuation.md"},w=Object.assign(m,{setup(f){const a=c(!0);a.value=!1;const{params:i}=n();return(g,t)=>(r(),o("div",null,[e("client-only",null,[e("eox-storytelling",{"show-nav":"","markdown-url":s(i).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,p)]),e("div",u,[a.value?(r(),o(l,{key:0},[t[0]||(t[0]=d(' --- cover-image: https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/population_all_residents.png domain: Sustainable Cities tags: flooding, evacuation, climate adaptation, traffic simulation, synthetic population, GEPOC, scenarify, SUMO provider: dwh,TU Wien,VRVis --- <h1 id="flood-evacuation" tabindex="-1">Flood Evacuation <a class="header-anchor" href="#flood-evacuation" aria-label="Permalink to &quot;Flood Evacuation&quot;">​</a></h1><h3 id="combining-population-data-dynamic-flood-modelling-and-traffic-simulation-to-support-evacuation-planning" tabindex="-1">Combining population data, dynamic flood modelling and traffic simulation to support evacuation planning <a class="header-anchor" href="#combining-population-data-dynamic-flood-modelling-and-traffic-simulation-to-support-evacuation-planning" aria-label="Permalink to &quot;Combining population data, dynamic flood modelling and traffic simulation to support evacuation planning &lt;!--{ style=&quot;font-size:1.5rem;opacity:0.7;margin-top:1rem;&quot; }--&gt;&quot;">​</a></h3><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Heavy precipitation has become more frequent and more intense over most land areas since the 1950s, and further warming will very likely intensify it in most regions (<a href="https://doi.org/10.1017/9781009157896.001" target="_blank" rel="noreferrer">IPCC, 2021</a>). In Austria, more intense heavy rainfall is expected to increase flood hazards, and summer floods are projected to become more frequent, particularly in small Alpine catchments (<a href="https://doi.org/10.1553/aar2-ch7" target="_blank" rel="noreferrer">Fuchs et al., 2025</a>).</p><p>Severe floods can force entire villages to be evacuated. In September 2024, seven settlements in Lower Austria’s Tullnerfeld region were evacuated after heavy rainfall (<a href="https://noe.orf.at/stories/3273454/" target="_blank" rel="noreferrer">ORF, 2024</a>). Therefore, municipalities in flood-prone areas should be prepared for evacuations.</p><p>In the POPSICLE research project, we investigate how simulation can support decisions on flood evacuation. A municipality preparing for an evacuation should aim to find answers to questions such as: Where could traffic accumulate? Which residential areas might be cut off? How many cars would get out, and when?</p><p>To answer these questions, we bring three models together. The population model <strong>GEPOC ABM</strong>, short for Generic Population Concept – Agent-Based Model (<a href="https://doi.org/10.1109/WSC.2018.8632170" target="_blank" rel="noreferrer">Bicher et al., 2018</a>, <a href="https://doi.org/10.48550/arXiv.2510.20840" target="_blank" rel="noreferrer">2025a</a>), describes where people live. The simulation platform <strong>scenarify</strong> by VRVis (<a href="https://www.vrvis.at/en/products-solutions/products-licenses/scenarify" target="_blank" rel="noreferrer">VRVis, n.d.-c</a>) describes which roads flood, and when. The open-source traffic simulator <strong>SUMO</strong> (<a href="https://doi.org/10.1109/ITSC.2018.8569938" target="_blank" rel="noreferrer">Alvarez Lopez et al., 2018</a>) combines the two: cars start at the residents&#39; homes and drive along a road network derived from OpenStreetMap (<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>) towards safe exit points, while the rising water gradually closes roads. We extended the functionalities of SUMO within this project to support the dynamic closing of streets and agent-specific knowledge about blocked roads.</p><p><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/flood-evacuation-overview.png" alt="Overview: population data from GEPOC ABM and flood data from scenarify serve as inputs to a traffic simulation based on SUMO"></p><p><em>Figure 1. Overview of the approach: population data from GEPOC ABM and flood data from scenarify serve as inputs to a traffic simulation based on SUMO.</em></p><p>We demonstrate the approach in the Möllbrücke–Sachsenburg area in Carinthia, which is an area at high risk of flooding.</p><h2 id="where-does-the-evacuation-begin" tabindex="-1">Where does the evacuation begin? <a class="header-anchor" href="#where-does-the-evacuation-begin" aria-label="Permalink to &quot;Where does the evacuation begin?&quot;">​</a></h2><p>The evacuation starts at people&#39;s homes. GEPOC ABM simulates the Austrian population and how it develops over time; each agent represents a person with a sex, an age and a place of residence given as geographic coordinates (<a href="https://doi.org/10.48550/arXiv.2510.20840" target="_blank" rel="noreferrer">Bicher et al., 2025a</a>). The model is openly parametrised and validated for Austria (<a href="https://doi.org/10.48550/arXiv.2511.00048" target="_blank" rel="noreferrer">Bicher et al., 2025b</a>, <a href="https://doi.org/10.1016/j.simpat.2026.103339" target="_blank" rel="noreferrer">2026</a>).</p><p>For this evacuation experiment, we use a single snapshot: the synthetic population coordinates that GEPOC ABM generated for 1 January 2025, which are published as open data (<a href="https://doi.org/10.48436/c4nk9-m2n74" target="_blank" rel="noreferrer">Giannandrea, 2026</a>). In the study area, the snapshot contains 1,833 synthetic residents at 1,121 home locations (Figure 2). The agents are assigned to existing buildings taken from OpenStreetMap, but they just statistically represent the population and do not identify the people who actually live there.</p><p><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/population_all_residents.png" alt="Home locations of all 1,833 synthetic residents in the Möllbrücke–Sachsenburg study area."></p><p><em>Figure 2. Home locations of all 1,833 synthetic residents in the Möllbrücke–Sachsenburg study area. Data: <a href="https://doi.org/10.48436/c4nk9-m2n74" target="_blank" rel="noreferrer">Giannandrea (2026)</a>; roads © OpenStreetMap contributors.</em></p><p>To estimate the number of cars, we apply the passenger-car ownership rate of the district of Spittal an der Drau, 663.7 cars per 1,000 residents (<a href="https://www.statistik.at/atlas/?mapid=them_kfz_bestand&amp;layerid=layer1&amp;sublayerid=sublayer1" target="_blank" rel="noreferrer">Statistics Austria, n.d.</a>). Based on the ratio, the study area has overall 1,217 cars. Each car is simulated individually and starts on a suitable road near to its home.</p><h2 id="which-roads-flood-and-when" tabindex="-1">Which roads flood, and when? <a class="header-anchor" href="#which-roads-flood-and-when" aria-label="Permalink to &quot;Which roads flood, and when?&quot;">​</a></h2><p>The flood information comes from <strong>scenarify</strong>, VRVis&#39;s web-based platform for hydrodynamic simulation, 3D visualisation and decision support (<a href="https://www.vrvis.at/en/products-solutions/products-licenses/scenarify" target="_blank" rel="noreferrer">VRVis, n.d.-c</a>). Its hydrodynamic model computes how water spreads across the terrain by solving the shallow water equations on a regular grid (<a href="https://scenarify.vrvis.at/help/modelDescription/introduction.html" target="_blank" rel="noreferrer">VRVis, n.d.-a</a>).</p><p>In <a href="./flood-validation">Validating Flood Scenarios from Space</a>, we show how satellite-derived flood maps can be used to validate simulations of historical floods.</p><p>For this study, we use a scenarify flood scenario for Sachsenburg, computed on a 1 m grid and covering about 3.4 × 2.3 km. We take three hours of the scenario and, for every minute, transfer the maximum water depth reached so far (<a href="https://scenarify.vrvis.at/help/modelDescription/results.html" target="_blank" rel="noreferrer">VRVis, n.d.-b</a>) to 10 m sections of the roads. From a depth of 10 cm, a road section closes to new traffic. If the water depth is below 10 cm, cars can still enter the street, but at a maximum speed of 5 km/h.</p><h2 id="how-do-drivers-react-to-the-water" tabindex="-1">How do drivers react to the water? <a class="header-anchor" href="#how-do-drivers-react-to-the-water" aria-label="Permalink to &quot;How do drivers react to the water?&quot;">​</a></h2><p>SUMO is an open-source microscopic traffic simulator: it models individual vehicles and their interactions on a road network (<a href="https://doi.org/10.1109/ITSC.2018.8569938" target="_blank" rel="noreferrer">Alvarez Lopez et al., 2018</a>). We substantially extended it within this research project and enabled it to model dynamically changing road conditions.</p><p>Agents know the road network and where the exits are. They discover road closures as they encounter them and remember which roads are blocked. When a road is closed, they turn around and look for another route to their destination. If they cannot find a route to the exit they originally wanted to reach, they try to find a different exit. Drivers also look for another route if they spend too long in a queue.</p><p>The first video shows a simulation run with a two-hour departure window. 1,217 cars are scheduled to leave home at random times spread evenly over the first two hours, each heading for one of nine exits.</p><p><video src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/evacuation_overview.mp4" poster="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/evacuation_video_still_0130.png" controls></video></p><p><em>Video 1. This video shows a two-hour departure run. Red roads are flooded and closed to new traffic. Light blue roads show shallow water.</em></p><p>To view the traffic and flooding together in 3D, we import the SUMO simulation results back into scenarify. The second video shows the simulated vehicles reacting to the floods in scenarify.</p><p><video src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/evacuation_scenarify.mp4" poster="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/evacuation_scenarify_still.jpg" controls preload="metadata"></video></p><p><em>Video 2. SUMO vehicle movements visualised together with scenarify&#39;s flood simulation.</em></p><h2 id="how-much-does-departure-timing-matter" tabindex="-1">How much does departure timing matter? <a class="header-anchor" href="#how-much-does-departure-timing-matter" aria-label="Permalink to &quot;How much does departure timing matter?&quot;">​</a></h2><p>We compare three departure windows under the same flood scenario: the same 1,217 cars, with the same homes and initial routes. The agents are scheduled to leave within one, two or three hours. The planned departure order stays the same across the three runs. Only the scheduled times are scaled to fit each window.</p><p>Times are given in simulation time, starting at 00:00. The floods rise from 00:00 to 03:00. All runs end at 03:30, and a car counts as evacuated only if it has reached an exit by then. Cars that become trapped or stranded remain on the road and continue to take up space.</p><p>With a one-hour departure window, 1,083 of 1,217 cars (89.0%) reach an exit. With a two-hour window, this falls to 776 (63.8%), and with a three-hour window to 528 (43.4%) (Figure 3). In this scenario, the sooner the cars set off, the more of them get out.</p><p><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/evacuation_success_by_window.png" alt="Number and percentage of all 1,217 planned cars reaching an exit for one-, two- and three-hour departure windows."></p><p><em>Figure 3. Number and percentage of all 1,217 planned cars reaching an exit for one-, two- and three-hour departure windows.</em></p><p>Figure 4 shows, for each area, the share of cars scheduled to leave from there that failed to reach an exit by the end of the simulation. With a one-hour window, these cars come mainly from the south-west of the study area around Sachsenburg, while Möllbrücke clears almost completely. With longer windows, the affected areas spread across Sachsenburg and into Möllbrücke. The maps show which residential areas are difficult to evacuate under each departure schedule.</p><p><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/flood-evacuation/home_area_failures.png" alt="Home areas of cars not evacuated at the end of a simulation run. Only cells containing modelled homes are coloured."></p><p><em>Figure 4. Home areas of cars not evacuated at the end of a simulation run. Only cells containing modelled homes are coloured. Data: <a href="https://doi.org/10.48436/c4nk9-m2n74" target="_blank" rel="noreferrer">Giannandrea (2026)</a>; roads © OpenStreetMap contributors.</em></p><h2 id="assumptions-and-limitations" tabindex="-1">Assumptions and limitations <a class="header-anchor" href="#assumptions-and-limitations" aria-label="Permalink to &quot;Assumptions and limitations&quot;">​</a></h2><p>This demonstration is a research proof of concept. The results depend on the input data and, among other things, on the assumptions below.</p><table tabindex="0"><thead><tr><th>Topic</th><th>Assumption</th></tr></thead><tbody><tr><td>Residents</td><td>All synthetic residents of the study area are at home when the evacuation starts.</td></tr><tr><td>Number of cars</td><td>The number of cars is derived from the district-average car ownership rate, and residents take all of their cars with them.</td></tr><tr><td>Departure times</td><td>Planned departure times are spread evenly over the time windows.</td></tr><tr><td>Driver knowledge</td><td>Drivers know the road network and the exits, but learn about flooded roads only when they reach them.</td></tr><tr><td>Water depth</td><td>The 10 cm closure threshold and the 5 km/h limit on shallower water are modelling assumptions.</td></tr></tbody></table><h2 id="from-simulation-to-municipal-planning" tabindex="-1">From simulation to municipal planning <a class="header-anchor" href="#from-simulation-to-municipal-planning" aria-label="Permalink to &quot;From simulation to municipal planning&quot;">​</a></h2><p>In this flood scenario, the time of departure makes a large difference. For the one-hour departure window, almost nine in ten cars reach an exit. In the scenario with the three-hour window, fewer than half of the cars successfully evacuate.</p><p>Scenario results like these let a municipality examine an evacuation before an emergency. Municipalities can use the results to identify road connections worth investigating, weigh the consequences of departure timing and see which areas may need additional planning attention. Comparing several scenarios reveals whether a bottleneck persists across conditions or belongs to one particular combination of flooding and traffic.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Alvarez Lopez, P., Behrisch, M., Bieker-Walz, L., Erdmann, J., Flötteröd, Y.-P., Hilbrich, R., Lücken, L., Rummel, J., Wagner, P., &amp; Wießner, E. (2018). Microscopic traffic simulation using SUMO. In <em>2018 21st International Conference on Intelligent Transportation Systems (ITSC)</em> (pp. 2575–2582). IEEE. <a href="https://doi.org/10.1109/ITSC.2018.8569938" target="_blank" rel="noreferrer">https://doi.org/10.1109/ITSC.2018.8569938</a></li><li>Bicher, M., Urach, C., &amp; Popper, N. (2018). GEPOC ABM: A generic agent-based population model for Austria. In <em>Proceedings of the 2018 Winter Simulation Conference (WSC)</em> (pp. 2656–2667). IEEE. <a href="https://doi.org/10.1109/WSC.2018.8632170" target="_blank" rel="noreferrer">https://doi.org/10.1109/WSC.2018.8632170</a></li><li>Bicher, M., Brunmeir, D., Rippinger, C., Urach, C., Viehauser, M., Giannandrea, D., Kastinger, H., &amp; Popper, N. (2025a). <em>GEPOC ABM, Generic Population Concept – Agent-Based Model, version 2.2</em> (arXiv:2510.20840). arXiv. <a href="https://doi.org/10.48550/arXiv.2510.20840" target="_blank" rel="noreferrer">https://doi.org/10.48550/arXiv.2510.20840</a></li><li>Bicher, M., Viehauser, M., Giannandrea, D., Kastinger, H., Brunmeir, D., Rippinger, C., Urach, C., &amp; Popper, N. (2025b). <em>GEPOC Parameters – Open source parametrisation and validation for Austria, version 2.0</em> (arXiv:2511.00048). arXiv. <a href="https://doi.org/10.48550/arXiv.2511.00048" target="_blank" rel="noreferrer">https://doi.org/10.48550/arXiv.2511.00048</a></li><li>Bicher, M., Viehauser, M., Giannandrea, D., Kastinger, H., Brunmeir, D., &amp; Popper, N. (2026). Novel concepts for agent-based population modelling and simulation: GEPOC ABM 2025. <em>Simulation Modelling Practice and Theory, 152</em>, 103339. <a href="https://doi.org/10.1016/j.simpat.2026.103339" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.simpat.2026.103339</a></li><li>Fuchs, S., Schöner, W., Steiger, R., et al. (2025). The Austrian Alps as multi-dimensional focal area. In D. Huppmann, M. Keiler, K. Riahi, &amp; H. Rieder (Eds.), <em>Second Austrian Assessment Report on Climate Change (AAR2) of the Austrian Panel on Climate Change (APCC)</em>, Chapter 7. Austrian Academy of Sciences Press. <a href="https://doi.org/10.1553/aar2-ch7" target="_blank" rel="noreferrer">https://doi.org/10.1553/aar2-ch7</a></li><li>Giannandrea, D. (2026). <em>Austrian synthetic population coordinates by GEPOC ABM</em> (Version 1) [Data set; reference date 1 January 2025]. TU Wien. <a href="https://doi.org/10.48436/c4nk9-m2n74" target="_blank" rel="noreferrer">https://doi.org/10.48436/c4nk9-m2n74</a></li><li>IPCC. (2021). Summary for policymakers. In V. Masson-Delmotte et al. (Eds.), <em>Climate change 2021: The physical science basis. Contribution of Working Group I to the Sixth Assessment Report of the Intergovernmental Panel on Climate Change</em> (pp. 3–32). Cambridge University Press. <a href="https://doi.org/10.1017/9781009157896.001" target="_blank" rel="noreferrer">https://doi.org/10.1017/9781009157896.001</a> (statements A.3.2 and B.2.4)</li><li>OpenStreetMap contributors. (n.d.). <em>OpenStreetMap</em> [Data set]. Available under the Open Database License. <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">Copyright and attribution</a></li><li>ORF. (2024, September 17). <em>Sieben Ortschaften evakuiert, vier Tote</em> [Seven localities evacuated, four dead]. noe.ORF.at. <a href="https://noe.orf.at/stories/3273454/" target="_blank" rel="noreferrer">https://noe.orf.at/stories/3273454/</a></li><li>Statistics Austria. (n.d.). <em>Kfz-Bestand 2024</em> [Motor vehicle stock 2024; interactive map]. STATatlas. <a href="https://www.statistik.at/atlas/?mapid=them_kfz_bestand&amp;layerid=layer1&amp;sublayerid=sublayer1" target="_blank" rel="noreferrer">STATatlas</a>: select 2024 → Motorisierungsgrad → Pkw → Bezirk Spittal an der Drau, which gives 663.7 passenger cars per 1,000 residents (50,139 registered passenger cars). For the study area, 1,833 × 0.6637 = 1,216.6, rounded to 1,217 cars; the passenger-car rate is applied directly, without a multiplier for the share of passenger cars among all motor vehicles.</li><li>VRVis. (n.d.-a). <em>Hydrodynamic simulation model</em>. scenarify documentation. Retrieved 22 October 2026, from <a href="https://scenarify.vrvis.at/help/modelDescription/introduction.html" target="_blank" rel="noreferrer">https://scenarify.vrvis.at/help/modelDescription/introduction.html</a></li><li>VRVis. (n.d.-b). <em>Results</em>. scenarify documentation. Retrieved 22 October 2026, from <a href="https://scenarify.vrvis.at/help/modelDescription/results.html" target="_blank" rel="noreferrer">https://scenarify.vrvis.at/help/modelDescription/results.html</a></li><li>VRVis. (n.d.-c). <em>scenarify®</em> [Product page]. Retrieved 22 October 2026, from <a href="https://www.vrvis.at/en/products-solutions/products-licenses/scenarify" target="_blank" rel="noreferrer">https://www.vrvis.at/en/products-solutions/products-licenses/scenarify</a></li></ul><h2 id="about-legals-and-subscription-information" tabindex="-1">About, legals and subscription information <a class="header-anchor" href="#about-legals-and-subscription-information" aria-label="Permalink to &quot;About, legals and subscription information&quot;">​</a></h2><h3 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h3><p>This narrative presents a research demonstrator developed within the <strong>POPSICLE project</strong> by dwh GmbH, TU Wien and VRVis.</p><p><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/logos/logo_dwh.png" alt="dwh GmbH logo" height="56" style="margin:0 32px 12px 0;"><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/logos/logo_tuwien.png" alt="TU Wien logo" height="56" style="margin:0 32px 12px 0;"><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/logos/logo_vrvis.png" alt="VRVis logo" height="56" style="margin:0 32px 12px 0;"></p><p>The Austrian Federal Ministry of Innovation, Mobility and Infrastructure (BMIMI, formerly BMK) supports POPSICLE through the <em>Digital Twin Austria 2023</em> call under its <em>Digitaler Zwilling Österreich</em> programme.</p><p>FFG is the central national funding organization and strengthens Austria&#39;s innovative power. POPSICLE (FFG-Project number 918405) is funded by FFG. <a href="http://www.ffg.at" target="_blank" rel="noreferrer">www.ffg.at</a></p><p><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/logos/BMIMI_Logo_srgb.png" alt="Austrian Federal Ministry of Innovation, Mobility and Infrastructure (BMIMI) logo" height="72" style="margin:0 32px 12px 0;"><img src="https://raw.githubusercontent.com/maximilianvie/public-narratives/refs/heads/main/assets/flood_narratives/logos/logo_ffg.png" alt="FFG Austrian Research Promotion Agency logo" height="80" style="margin:0 32px 12px 0;"></p><p>Contact: <a href="mailto:office@dwh.at" target="_blank" rel="noreferrer">office@dwh.at</a></p><h3 id="access-and-subscription" tabindex="-1">Access and subscription <a class="header-anchor" href="#access-and-subscription" aria-label="Permalink to &quot;Access and subscription&quot;">​</a></h3><p>The flood evacuation simulation is a research demonstrator, not an operational evacuation service. The synthetic population coordinates (<a href="https://doi.org/10.48436/c4nk9-m2n74" target="_blank" rel="noreferrer">Giannandrea, 2026</a>) are openly available from TU Wien Research Data under the Creative Commons Attribution 4.0 licence (CC BY 4.0), and SUMO is open-source software under the Eclipse Public License 2.0. The simulation platform scenarify is offered by VRVis as a subscription service (<a href="https://www.vrvis.at/en/products-solutions/products-licenses/scenarify" target="_blank" rel="noreferrer">VRVis, n.d.-c</a>).</p><h3 id="copyright-and-citation" tabindex="-1">Copyright and citation <a class="header-anchor" href="#copyright-and-citation" aria-label="Permalink to &quot;Copyright and citation&quot;">​</a></h3><p>Copyright for this narrative and the capability it describes resides with the providers named above. Map data © OpenStreetMap contributors, available under the Open Database License. Please cite this narrative as: dwh GmbH, TU Wien and VRVis (2026). <em>Flood Evacuation</em>. GTIF Austria narrative. Please also cite the underlying models and data listed in the references.</p>',59))],64)):h("",!0)])]))}});export{b as __pageData,w as default};
